{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The load balancer listener is configured to use HTTP on port 80, which transmits data in cleartext and exposes it to interception or modification."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "Ensure that load balancer is using at least TLS 1.2",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "Since the listener uses HTTP instead of HTTPS, it does not enforce any TLS version, failing to meet the minimum security standard of TLS 1.2 for encrypted traffic."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-TLS-1-2-2017-01\"\n  certificate_arn   = var.certificate_arn # User must provide a valid ACM certificate ARN\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}\n\nvariable \"certificate_arn\" {\n  description = \"ARN of the ACM certificate to use for HTTPS\"\n  type        = string\n}",
  "fix_summary": "Changed the listener protocol from HTTP to HTTPS, updated the port to 443, added an SSL policy enforcing TLS 1.2, and included a required variable for the certificate ARN to enable encryption."
}
